class SerialGenerator {
  final String gcp;
  int _counter = 0;
  final Random _rand = Random.secure();

  SerialGenerator(this.gcp);

  /// Sequential: predictable, easy to sort, but exposes production volume.
  String nextSequential() => '${_counter++}';

  /// Random 16-char alphanumeric — must dedup on generation.
  String nextRandom(Set<String> issued) {
    while (true) {
      final buf = StringBuffer();
      for (int i = 0; i < 16; i++) {
        buf.write(_alphabet[_rand.nextInt(_alphabet.length)]);
      }
      final s = buf.toString();
      if (issued.add(s)) return s;
    }
  }

  /// HMAC-based: serial doubles as a signature. Verifiable without DB lookup.
  String nextHmac(int counter, String key) {
    final data = utf8.encode('$gcp-$counter');
    final hmac = Hmac(sha256, utf8.encode(key)).convert(data).toString().substring(0, 16);
    return hmac.toUpperCase();
  }

  static const _alphabet = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789';
}

// SGTIN URN
String sgtinUrn({required String gtin14, required String serial}) {
  // Remove indicator digit + check digit from GTIN-14 to derive GCP + itemRef.
  final gcpLen = 7;   // varies; look up in table
  final gcp = gtin14.substring(1, 1 + gcpLen);
  final itemRef = gtin14.substring(1 + gcpLen, 13);
  return 'urn:epc:id:sgtin:$gcp.$itemRef.$serial';
}

// AI (21) allows up to 20 alphanumeric characters — enormous space.
// If sequential integers, 20-digit range is 10^20 — practically inexhaustible for a single brand.
// But brand owners often partition by:
//   - plant (first 2 chars indicate site)
//   - year of production (next 2 chars)
//   - sequence within (remaining)
// e.g., 'IN26' + '00000001' = plant India, 2026, serial 1.

// Reuse policy: GS1 recommends NEVER reusing an SGTIN serial for the same GTIN
// for at least 4 years after decommissioning. Some regulators require 10 years.

// Collision defense: for random-generated serials, DB unique constraint on
// (gtin, serial) — insert-then-fail-then-retry pattern with jitter.
